import clsx from 'clsx';
import { Link, useNavigate } from 'react-router-dom';
import { useState } from 'react';
import { toast } from 'react-toastify';

import Button from '../../components/Button/Button';
import styles from '../../assets/css/Auth/auth.module.scss';
import Input from '../../components/Input/Input';
import authApi from '../../services/api/auth/authApi';
import { handleLocalStorage } from '../../utils/handleLocalStorage';
import { useCheckSignedIn } from '../../customs/hooks';
import { Role } from '../../utils/enums/Role';

function Signin() {
    const [showPassword, setShowPassword] = useState(false);

    const togglePasswordVisibility = () => {
        setShowPassword((prevState) => !prevState);
    };
    const [signinRequest, setSigninRequest] = useState({
        email: '',
        password: '',
    });

    // eslint-disable-next-line no-unused-vars
    const [isSignedIn, setIsSignedIn] = useCheckSignedIn();
    // console.log(isSignedIn);

    const handleChangeInput = (e) => {
        setSigninRequest((prevState) => {
            const newState = {
                ...prevState,
                [e.target.name]: e.target.value,
            };
            return newState;
        });
    };

    const navigate = useNavigate();

    // khi đăng nhập sai thông tin thì dùng cái này để css
    const [failed, setFailed] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const siginResponse = await authApi.signin(signinRequest);
            // Xóa thông tin cũ trước khi lưu thông tin mới (xoá cho chắc thôi chứ signout xoá rồi)
            handleLocalStorage.clearToken();
            const { email, role } = siginResponse.data;
            handleLocalStorage.setToken(email, role);

            toast.success(siginResponse.message);
            setFailed(false);
            setIsSignedIn(true);

            // chuyển hướng
            const currentRole = handleLocalStorage.getCurrentRole();
            if (currentRole === Role.ADMIN) {
                navigate('/Admin');
            } else {
                navigate('/');
            }
        } catch (error) {
            // Thông báo đã được cài trong axiosClient rồi nên ở đây khỏi
            console.error('Login failed:', error);
            setFailed(true);
        }
    };

    return (
        <div className={clsx(styles.authContainer)}>
            <form onSubmit={handleSubmit} className={clsx(styles.signinBox, 'flex-column')}>
                <div className='font-size-24px mb-3 d-flex flex-column'>
                    <span className='font-cera-round-pro-yellow'>
                        Welcome Back
                        <i className='fa-solid fa-face-laugh ms-2'></i>
                    </span>
                    <span className='font-cera-round-pro-black font-size-32px'>Sign In to Your Account</span>
                </div>

                <div className={`input-box d-flex flex-column ${styles.inputGroup}`}>
                    <div className={styles.inputBox}>
                        <label htmlFor='email' className='font-cera-round-pro-bold ms-2'>
                            Email Address
                        </label>
                        <Input
                            className={clsx('mb-3', { [styles.failed]: failed })}
                            type={'email'}
                            placeholder={'e.g. user001@gmail.com'}
                            name='email'
                            value={signinRequest.email}
                            onChange={(e) => handleChangeInput(e)}
                            required
                        />
                    </div>

                    <div className={styles.inputBox}>
                        <label htmlFor='password' className='font-cera-round-pro-bold ms-2'>
                            Password{' '}
                            <span onClick={togglePasswordVisibility} className={styles.iconShowHide}>
                                {showPassword ? (
                                    <i className='fa-regular fa-eye' title='Hide password?'></i>
                                ) : (
                                    <i className='fa-regular fa-eye-slash' title='Show password?'></i>
                                )}
                            </span>
                        </label>
                        <Input
                            className={clsx('mb-3', { [styles.failed]: failed })}
                            type={showPassword ? 'text' : 'password'}
                            placeholder={'Enter your password...'}
                            name='password'
                            value={signinRequest.password}
                            onChange={(e) => handleChangeInput(e)}
                            required
                        />
                    </div>

                    <div className='mb-2'>
                        <Link to={'/forgot-password'}>Forgot your password?</Link>
                    </div>
                </div>

                <Button className='font-size-20px' type='submit'>
                    Sign in
                    <i className='fas fa-sign-in-alt ms-2'></i>
                </Button>

                <div className='font-cera-round-pro-regular'>
                    New here?
                    <Link to={'/sign-up'} className='text-underline ms-2'>
                        Create your account now
                    </Link>
                </div>
            </form>
        </div>
    );
}

export default Signin;
